using System.Collections.Immutable;
using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Text;

using static Macaron.DependencyInjection.Generator.HintNameHelpers;

namespace Macaron.DependencyInjection.Generator;

[Generator]
public sealed class DependencyInjectionGenerator : IIncrementalGenerator
{
    private const string RegistrationExtensionsSource =
        """
        // <auto-generated />
        #nullable enable

        namespace Macaron.DependencyInjection
        {
            internal static class DependencyRegistrarExtensions
            {
                internal static void Register<T>(
                    this global::Macaron.DependencyInjection.IDependencyRegistrar registrar,
                    global::Macaron.DependencyInjection.Lifetime lifetime,
                    object? tag = null,
                    global::System.Action<T>? cleanup = null)
                    where T : notnull
                {
                    Register<T, T>(registrar, lifetime, tag, cleanup);
                }

                internal static void RegisterTransient<T>(
                    this global::Macaron.DependencyInjection.IDependencyRegistrar registrar,
                    object? tag = null,
                    global::System.Action<T>? cleanup = null)
                    where T : notnull
                {
                    Register<T, T>(registrar, global::Macaron.DependencyInjection.Lifetime.Transient, tag, cleanup);
                }

                internal static void RegisterScoped<T>(
                    this global::Macaron.DependencyInjection.IDependencyRegistrar registrar,
                    object? tag = null,
                    global::System.Action<T>? cleanup = null)
                    where T : notnull
                {
                    Register<T, T>(registrar, global::Macaron.DependencyInjection.Lifetime.Scoped, tag, cleanup);
                }

                internal static void RegisterSingleton<T>(
                    this global::Macaron.DependencyInjection.IDependencyRegistrar registrar,
                    object? tag = null,
                    global::System.Action<T>? cleanup = null)
                    where T : notnull
                {
                    Register<T, T>(registrar, global::Macaron.DependencyInjection.Lifetime.Singleton, tag, cleanup);
                }

                internal static void Register<TService, TImplementation>(
                    this global::Macaron.DependencyInjection.IDependencyRegistrar registrar,
                    global::Macaron.DependencyInjection.Lifetime lifetime,
                    object? tag = null,
                    global::System.Action<TService>? cleanup = null)
                    where TService : notnull
                    where TImplementation : notnull, TService
                {
                    var factory = global::Macaron.DependencyInjection.Generated.Factories.Get<TImplementation>();

                    global::Macaron.DependencyInjection.DependencyFactory<TService> serviceFactory =
                        (global::Macaron.DependencyInjection.IDependencyResolver resolver, ref global::Macaron.DependencyInjection.CleanupCollector collector) =>
                        {
                            return factory(resolver, ref collector);
                        };

                    global::Macaron.DependencyInjection.IDependencyRegistrarExtensions.Register<TService>(
                        registrar,
                        serviceFactory,
                        lifetime,
                        tag,
                        cleanup);
                }

                internal static void RegisterTransient<TService, TImplementation>(
                    this global::Macaron.DependencyInjection.IDependencyRegistrar registrar,
                    object? tag = null,
                    global::System.Action<TService>? cleanup = null)
                    where TService : notnull
                    where TImplementation : notnull, TService
                {
                    Register<TService, TImplementation>(
                        registrar,
                        global::Macaron.DependencyInjection.Lifetime.Transient,
                        tag,
                        cleanup);
                }

                internal static void RegisterScoped<TService, TImplementation>(
                    this global::Macaron.DependencyInjection.IDependencyRegistrar registrar,
                    object? tag = null,
                    global::System.Action<TService>? cleanup = null)
                    where TService : notnull
                    where TImplementation : notnull, TService
                {
                    Register<TService, TImplementation>(
                        registrar,
                        global::Macaron.DependencyInjection.Lifetime.Scoped,
                        tag,
                        cleanup);
                }

                internal static void RegisterSingleton<TService, TImplementation>(
                    this global::Macaron.DependencyInjection.IDependencyRegistrar registrar,
                    object? tag = null,
                    global::System.Action<TService>? cleanup = null)
                    where TService : notnull
                    where TImplementation : notnull, TService
                {
                    Register<TService, TImplementation>(
                        registrar,
                        global::Macaron.DependencyInjection.Lifetime.Singleton,
                        tag,
                        cleanup);
                }
            }
        }

        """;

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        var analysisCompilations = context.CompilationProvider.SelectMany(static (compilation, cancellationToken) =>
        {
            if (compilation.ReferencedAssemblyNames.All(identity => identity.Name != "Macaron.DependencyInjection"))
            {
                return ImmutableArray<CSharpCompilation>.Empty;
            }

            // 출력 전에도 등록 호출의 오버로드를 판별할 수 있도록 분석용 선언을 추가한다.
            var parseOptions = (CSharpParseOptions?)compilation.SyntaxTrees.FirstOrDefault()?.Options;
            var registrationExtensions = CSharpSyntaxTree.ParseText(
                text: RegistrationExtensionsSource,
                options: parseOptions,
                cancellationToken: cancellationToken
            );

            return ImmutableArray.Create(((CSharpCompilation)compilation).AddSyntaxTrees(registrationExtensions));
        });

        context.RegisterSourceOutput(
            source: analysisCompilations,
            action: static (output, _) =>
            {
                var hintName = GetAssemblyHintName(
                    sourceName: "DependencyRegistrarExtensions",
                    assemblyIdentity: typeof(DependencyInjectionGenerator).Assembly.FullName
                );

                output.AddSource(
                    hintName: $"{hintName}.g.cs",
                    sourceText: SourceText.From(RegistrationExtensionsSource, Encoding.UTF8)
                );
            }
        );

        var constructionCandidates = context
            .SyntaxProvider
            .CreateSyntaxProvider(
                predicate: static (node, _) => ConstructionDiscovery.IsConstructionCandidate(node),
                transform: static (syntax, _) => syntax.Node.GetReference()
            );

        var generation = analysisCompilations
            .Combine(constructionCandidates.Collect())
            .Select(static (data, cancellationToken) => ConstructionDiscovery.CreateDefinitions(
                requests: ConstructionDiscovery.Discover(
                    references: data.Right,
                    compilation: data.Left,
                    cancellationToken
                ),
                sourceCompilation: data.Left,
                cancellationToken
            ))
            .WithTrackingName("FactoryGeneration");

        context.RegisterSourceOutput(
            source: generation,
            action: static (output, result) =>
            {
                foreach (var diagnostic in result.Diagnostics)
                {
                    output.ReportDiagnostic(diagnostic);
                }
            }
        );

        var creationSources = generation
            .SelectMany(static (result, _) => result.Creations)
            .Select(static (definition, _) => (definition.HintName, Source: CreationRenderer.Render(definition)))
            .WithTrackingName("CreationSource");

        context.RegisterSourceOutput(
            source: creationSources,
            action: static (output, creation) =>
            {
                output.AddSource(creation.HintName, SourceText.From(creation.Source, Encoding.UTF8));
            }
        );

        var injectionSources = generation
            .SelectMany(static (result, _) => result.Injections)
            .Select(static (definition, _) => (definition.HintName, Source: InjectionRenderer.Render(definition)))
            .WithTrackingName("InjectionSource");

        context.RegisterSourceOutput(
            source: injectionSources,
            action: static (output, injection) =>
            {
                output.AddSource(injection.HintName, SourceText.From(injection.Source, Encoding.UTF8));
            }
        );

        var entryPoints = context.SyntaxProvider.CreateSyntaxProvider(
            predicate: static (node, _) => InjectionEntryPointValidation.IsCandidate(node),
            transform: static (syntax, _) => syntax.Node.GetReference()
        );

        context.RegisterSourceOutput(
            source: analysisCompilations.Combine(entryPoints.Collect()),
            action: static (output, data) =>
            {
                foreach (var diagnostic in InjectionEntryPointValidation.Validate(
                    references: data.Right,
                    sourceCompilation: data.Left,
                    cancellationToken: output.CancellationToken
                ))
                {
                    output.ReportDiagnostic(diagnostic);
                }
            }
        );

        var assemblyIdentity = context
            .CompilationProvider
            .Select(static (compilation, _) => compilation.Assembly.Identity.ToString());

        // 진단 위치가 달라져도 렌더링을 재사용하도록 출력 정의만 값으로 비교한다.
        var definitions = generation
            .Select(static (result, _) => result.Definitions)
            .WithComparer(FactoryDefinitionsComparer.Instance);

        var factoriesSource = definitions
            .Select(static (factories, _) => FactoriesRenderer.Render(factories))
            .WithTrackingName("FactoriesSource");

        context.RegisterSourceOutput(
            source: factoriesSource.Combine(assemblyIdentity),
            action: static (output, data) =>
            {
                var hintName = GetAssemblyHintName(
                    sourceName: "Factories",
                    assemblyIdentity: data.Right
                );

                output.AddSource(
                    hintName: $"{hintName}.g.cs",
                    sourceText: SourceText.From(data.Left, Encoding.UTF8)
                );
            }
        );
    }
}
